//private boolean newWithinBundle;
/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "append">boolean</param>
void  create(boolean  append)
{
    SalesLine       prevSalesLine, nextSalesLine, curSalesLine;

    prevSalesLine   = this.cursor();
    nextSalesLine   = SalesLine::find(prevSalesLine.SalesId, prevSalesLine.nextLineNum());

    next create(append);

    curSalesLine    = this.cursor();

    curSalesLine.LineNum = SalesLine::lastLineNum(curSalesLine.SalesId) + 1;

    if (nextSalesLine.RevRecBundleParent)
    {
        curSalesLine.LineNum = SalesLine::AVAnewLineNumAfterBundle(nextSalesLine.SalesId, nextSalesLine.RevRecBundleParent);
        //newWithinBundle = true;
    }

}

void write()
{
    SalesLine       salesLine;
    FormDataSource  salesTableDS;

    next Write();

    //if (newWithinBundle)
    //{
    salesLine = this.cursor();
    salesTable::AVAreorgLineNum(salesLine.SalesId);
    salesTableDS = this.formRun().dataSource(formDataSourceStr(SalesTable, SalesTable));
    salesTableDS.reread();
    salesTableDS.refresh();
    //}
}
